// Converte o webhook da Evolution API (evento messages.upsert) em um formato simples.
const saida = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const evento = String(b.event || '').toLowerCase().replace('_', '.');
  if (evento !== 'messages.upsert') continue;
  const d = Array.isArray(b.data) ? b.data[0] : b.data;
  if (!d || !d.key) continue;

  let jid = d.key.remoteJid || '';
  if (jid.endsWith('@lid')) jid = d.key.remoteJidAlt || d.key.senderPn || '';
  if (!jid || /@(g\.us|broadcast|newsletter)$/.test(jid)) continue; // ignora grupos, status e canais
  const whatsapp = jid.split('@')[0].split(':')[0].replace(/\D/g, '');
  if (!whatsapp) continue;

  const m = d.message || {};
  const doc = m.documentMessage || m.documentWithCaptionMessage?.message?.documentMessage;
  let texto = m.conversation || m.extendedTextMessage?.text || m.imageMessage?.caption || m.videoMessage?.caption
    || doc?.caption || m.buttonsResponseMessage?.selectedDisplayText || m.listResponseMessage?.title
    || m.templateButtonReplyMessage?.selectedDisplayText || '';
  let tipo = 'texto';
  if (m.reactionMessage || m.protocolMessage || m.pollUpdateMessage) continue;
  if (m.audioMessage) tipo = 'audio';
  else if (m.imageMessage) { tipo = 'imagem'; texto = `[O cliente enviou uma imagem${texto ? ' com a legenda: ' + texto : ''}]`; }
  else if (doc) { tipo = 'documento'; texto = `[O cliente enviou o documento "${doc.fileName || 'arquivo'}"${doc.caption ? ' com a legenda: ' + doc.caption : ''}]`; }
  else if (m.videoMessage) { tipo = 'video'; texto = `[O cliente enviou um vídeo${texto ? ' com a legenda: ' + texto : ''}]`; }
  else if (m.stickerMessage) { tipo = 'figurinha'; texto = '[O cliente enviou uma figurinha]'; }
  else if (m.locationMessage) { tipo = 'localizacao'; texto = '[O cliente enviou uma localização]'; }
  else if (m.contactMessage) { tipo = 'contato'; texto = `[O cliente enviou um contato: ${m.contactMessage.displayName || ''}]`; }
  if (tipo === 'texto' && !String(texto).trim()) continue;

  saida.push({ json: {
    instancia: b.instance,
    whatsapp,
    wa_message_id: d.key.id || '',
    from_me: !!d.key.fromMe,
    nome_whatsapp: d.pushName || '',
    tipo,
    texto: String(texto).trim(),
    audio_base64: tipo === 'audio' ? (m.base64 || d.base64 || '') : '',
    audio_mime: (m.audioMessage?.mimetype || 'audio/ogg').split(';')[0],
  }});
}
return saida;

